    },
    {
      "card_ids": ["C03"],
      "claim": "Corynoline crossed the BBB in mice with relatively high brain concentrations, supporting CNS access for methylenedioxy-containing alkaloids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Corydaline was detected in rat CSF and reached brain levels close to other tissues after oral dosing, providing direct evidence of BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tetrahydropalmatine was detected in rat CSF, confirming BBB penetration for the tetrahydroprotoberberine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dauricine crossed the BBB in rats, although P-gp efflux modulated its brain levels; this indicates transporter liability does not preclude meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query noscapine has favorable passive BBB properties and is strongly supported by high-transfer alkaloid analogues that directly demonstrate brain/CSF penetration. Low-transfer negative records involve structurally dissimilar quaternary ammonium, dimeric, or radioligand molecules and do not override this evidence. Therefore, meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct noscapine-specific brain/CSF measurement is included in the provided records; the decision relies on high-transfer alkaloid analogues.",
    "The brain tumor/glioma condition may alter BBB integrity, and evidence from normal animals may not fully capture the tumor microenvironment."
  ],
